scripts.宝箱.txt:
//打开宝箱

	If ($Openboxzhao == 1) @Open1; 
	
	PlaySound("特_捡到特殊物品.wav");
	OpenBox();
	Say("箱子里什么也没有。");
	Assign($Openboxzhao, 1);
	Return;
	
@Open1:
	Say("包裹下面好像藏着什么……");
	AddGoods("Goods079_游龙披风.ini");
	Sleep(600);
	Say("得到五十两银子。");
	AddMoney(50);
	SetObjScript("","");
	Return;

scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

