traps.Trap02.txt:
// 第一次进赵七娘家

	If ($Eventzhaoqi == 0) @Eventzhaoqi0;
	
@Eventzhaoqi0:
	Say("赵七娘：哎呀呀，菩萨好灵验啊。", 0);
	PlayerGoto(12, 38);
	NpcGoto("赵七娘", 11, 33);
	NpcGoto("赵七娘", 11, 37);
	SetNpcDir("赵七娘", 7);
	SetPlayerDir(3);
	Say("赵七娘：奴家今天早上一起来就向菩萨祷告，希望今天有个男人走进我的屋里。你果然来了，还长得这么年轻英俊，比奴家想象的不知好出多少倍了。", 0);
	Say("赵七娘：奴家守寡三年，天天望，时时望，终于把你望来了，奴家这就给你预备酒菜。", 0);	
	
	NpcGoto("赵七娘", 9, 38);
	PlayerRunTo(10, 38);
	SetNpcDir("赵七娘", 6);
	Watch("独孤剑", "赵七娘", 0);
	Say("独孤剑：这位大嫂，你可能误会了，我……", 4);
	Say("赵七娘：大嫂？！我有那么老么？！", 0);
	Say("独孤剑：啊，不不不，我不是这个意思……在下告……告辞了！", 4);
	Say("赵七娘：公子怎么能说来就来说走就走呢？别急嘛，稍坐一下，酒菜很快就会预备好了。", 0);
	
	NpcGoto("赵七娘", 5, 37);
	SetNpcDir("赵七娘", 0);
	Say("独孤剑：大姐，你真的误会了！", 4);
	PlayerRunTo(6, 36);
	SetPlayerDir(1);
	SetNpcDir("赵七娘", 5);
	Say("独孤剑：大姐，在下并非拈花惹草之辈，冒昧走进大姐房中是因为……", 4);
	Say("赵七娘：一个大男人无缘无故走进一个年轻貌美的寡妇人家卧房里是因为什么？", 0);
	Say("独孤剑：我……我……", 4);
	Say("赵七娘：我什么我？奴家是真心喜欢你才留你的，你把奴家当成什么人了？", 0);
	Say("赵七娘：你们这些臭男人，装模作样背一把剑到处乱窜，见到放宝物的箱子就翻，见到女孩子的闺房就钻，还自称什么李大侠张大侠赵大侠，真是笑死人了。你说，你跑进来准备干什么？", 0);
	Say("独孤剑（暗忖）：<color=blue>这个女人真难应付，我得想个办法脱身……有了！<color=black>", 1);
	Say("独孤剑：我……是因为我在街上碰见一个人，他对大姐你仰慕得很，要我来帮他打探一下大姐的意思。", 2);
	Say("赵七娘：真的？这人是谁？我怎么知道你说的是不是真的？", 0);
	Say("独孤剑：我这就去帮你把他叫来。", 1);
	Say("赵七娘：哼，想来个金蝉脱壳？别打歪主意了，奴家等了三年才等到你上门，怎么会轻易放你走呢？", 0);
	Say("独孤剑：大姐，你应该对自己有点信心嘛，像你这么年轻漂亮的女子，有人暗自倾慕也是很正常的呀！你说我骗你，岂不是对自己没有信心吗？", 2);
	Say("赵七娘：你说的也有道理，那……好吧，你就去帮我把那人找来，让我看看那人是不是真心地喜欢奴家……", 0);
	SetNpcDir("赵七娘", 0);
	
	Memo("在寡妇赵七娘家被她缠住，答应帮她找一个仰慕她的人，方才脱身。");
	Assign($Eventzhaoqi, 1);
	SetMapTrap(2, "");
	Return;

traps.Trap03.txt:
// 第二次进赵七娘家

	If ($Eventzhaoqi == 2) @Eventzhaoqi2;
	Return;
	
@Eventzhaoqi2:	
	MoveScreen(4, 50, 2);
	Say("赵七娘：相公！", 0);
	Say("周木匠：娘子！", 0);
	Say("赵七娘：奴家等你好久了！", 0);
	Say("周木匠：我也是！");
	Say("赵七娘：从此我们要在一起恩恩爱爱过日子。", 0);
	Say("周木匠：我要去挣好多好多的钱，让你穿最新的衣服，带最好的首饰，让你成为临安最漂亮的女人。", 0);
	Say("赵七娘：你这么疼我，我一定给你……", 0);
	Say("周木匠：给我什么？", 0);
	Say("赵七娘：奴家怎么好说嘛。", 0);
	Say("周木匠：是不是……是不是给我生个大胖儿子？", 0);
	Say("周木匠：哈哈哈！我周木匠就要有后啦！哈哈哈！", 0);
	SetPlayerScn();
	PlayerGoto(10, 27);
	SetPlayerDir(3);
	Say("独孤剑：对不起，打搅二位，不知二位相互中意否？", 2);
	SetNpcDir("赵七娘", 0);
	SetNpcDir("周木匠", 7);
	Say("赵七娘：哎呀，只顾高兴，把你给忘了，你是我们的大媒人，我们要好好谢谢你。想当初，真是不好意思，不提了。", 0);
	Say("周木匠：是啊，我终于知道情为何物了，真该谢谢你。我这有一坛十年佳酿，现在赠送给你，谢谢你给我找了这么一位好娘子。", 0);
	Say("赵七娘：我这屋子里的东西，如果公子有用得上的，请尽管拿去，不必客气。", 0);
	Watch("周木匠", "赵七娘", 0);
	AddGoods("Goods207_十年佳酿.ini");
	Memo("妙计撮合了周木匠和赵七娘的美满姻缘。");
	Assign($Eventzhaoqi, 3);
	SetMapTrap(3, "");
	Return;
